blocks.source:
[Audited("capture")]
public async Task<long> Capture(long[] amounts) {
    if (amounts.Length == 0) return 0;
    await Task.Yield();
    long Fee(long value) { return value / 100; }
    return amounts.Where(x => x > 0).Select(x => x - Fee(x)).Sum();
}

